#!/bin/bash
cd /home/user/projects/matchhold/rebranding || exit 1
S=/tmp/claude-1000/-home-user-projects-matchhold/7b41e65d-5e68-4a3d-92c6-7055445f73e0/scratchpad
DAY='Cozy fantasy village match-3 game art. Warm, soft, matte hand-painted 3D look: chunky rounded forms, soft ambient occlusion, gentle gradients, NO glossy plastic highlights, NO specular shine. Warm afternoon light from the top-left. Palette: warm sand beige, honey gold, chestnut brown, sage green, muted terracotta, cream white.'
NIGHT='Cozy fantasy match-3 game art at night. Same warm, soft, matte hand-painted 3D look as the day art (NO glossy plastic highlights). Deep indigo and navy shadows, cool moonlight from the top-left, warm torch-orange accents, soft rim light and a gentle glow on key details.'
NEG='Avoid: text, letters, numbers, logos, watermark, signature, UI overlay, photorealism, harsh gloss, lens flare, pixel art, thick black outlines, extra objects, multiple views, collage, characters, birds, frame, pink or magenta colors inside the artwork.'
gen() { # out refs size prompt
  codex exec -m gpt-5.6-terra -c model_reasoning_effort=medium --sandbox workspace-write \
  "Use the built-in image_gen tool (imagegen skill) to generate ONE image. The attached images are references: follow them where the prompt says so, otherwise use them for mood, palette and material only. Target size $3 (resize/cover-crop with ImageMagick if the native size differs, no stretching). PNG. $4 $NEG Save the final PNG to exactly: /home/user/projects/matchhold/rebranding/$1 . Do not overwrite existing files. Print the saved path and dimensions." -i $2 \
  > "$S/$(basename $1).log" 2>&1
}
E=out/env
SCENE="the same scene as the attached full background (windmill on the left hill, cottages left and right, dirt road, rolling hills, forest, distant mountains, small lake)"
MP3="[DAY] MIDDLE layer for a tall phone screen (vertical 1:2) with a genuinely TRANSPARENT background (real alpha channel, no colored background, no magenta), stage 3. It sits over the first attached far portrait layer, with the same scene and style as the second attached image (the wide landscape middle layer of stage 3). Ground-level scenery seen straight on, ONLY in the bottom 30% of the canvas: a soft grassy ground strip across the full width, and on the LEFT and on the RIGHT side (each only the outer 30% of the width) one small cluster: a piece of a stone town wall with a small tower, one or two tall houses with red and blue roofs, a cobbled road. Buildings stand on a ground line at about 88% of the height and are about 12% of the canvas height tall. IMPORTANT: everything drawn is FULLY OPAQUE solid painting, with no mist, no haze, no fog, no semi-transparent gradients and no washed-out pale look; the grass strip is solid opaque green with a clean soft top edge. Everything above the buildings and grass is fully transparent, and the central 40% of the width above the grass strip is fully transparent. Slightly muted colors, low contrast, simplified details, gentle soft focus, no bright accents. Natural soft edges, no straight cut lines."
gen $E/bg/bg_s3_mid_day_port_v2.png "$E/bg/bg_s3_far_day_port_v1.png $E/bg/bg_s3_mid_day_land_v1.png $E/bg/bg_s2_mid_day_port_v1.png" 1440x2880 "$DAY $MP3" &
FGDP="[DAY] Out-of-focus FOREGROUND framing layer for a tall phone screen (vertical 1:2) with a genuinely TRANSPARENT background (real alpha channel, no colored background, no magenta). COMPACT organic vignette of blurry sage-green leaves, a leafy branch, ivy and a few small white flowers in the top-left and top-right corners (each only about 25% of the width and 12% of the height), and small grass tufts and mossy stones tucked into the bottom-left and bottom-right corners (each only the outer 16% of the width and the bottom 14% of the height). The foliage trails off NATURALLY: every leaf and stem ends with its own soft rounded organic tip, NO straight vertical or horizontal cut edges. Everything else on the canvas is fully transparent, in particular the lower area right above the bottom corners must stay open so buildings behind can be seen. Strong depth-of-field blur (bokeh), soft edges."
gen $E/fg/fg_day_port_v2.png "$E/fg/fg_day_land_v2.png $E/fg/fg_day_port_v1.png" 1440x2880 "$DAY $FGDP" &
wait
echo DONE
